import { query } from '../config/db.js';

/**
 * Creates a new account in the PostgreSQL database.
 *
 * Requirements enforced:
 * - Only the account name is accepted as an input argument.
 * - ID is generated by Postgres via gen_random_uuid().
 * - Initial balance is generated by Postgres via default 0.00.
 * - created_at is generated by Postgres via default CURRENT_TIMESTAMP.
 *
 * @param {string} name - Account holder name
 * @returns {Promise<object>} The created account record
 */
export const createAccount = async (name) => {
  const sql = `
    INSERT INTO accounts (name)
    VALUES ($1)
    RETURNING id, name, balance, created_at;
  `;

  const result = await query(sql, [name]);
  return result.rows[0];
};

/**
 * Fetches the current balance for an account by ID.
 * Checks account existence and throws 404 error if not found.
 *
 * @param {string} accountId - Account UUID
 * @returns {Promise<{ account_id: string, balance: string }>}
 */
export const getAccountBalance = async (accountId) => {
  const sql = `
    SELECT id AS account_id, balance
    FROM accounts
    WHERE id = $1;
  `;

  const result = await query(sql, [accountId]);

  if (result.rowCount === 0) {
    const error = new Error(`Account with ID '${accountId}' was not found.`);
    error.status = 404;
    throw error;
  }

  return result.rows[0];
};
